  <script>
    const items = [...document.querySelectorAll('.cart-item')];
    const subtotalEl = document.getElementById('subtotal');
    const deliveryEl = document.getElementById('delivery');
    const vatEl = document.getElementById('vat');
    const totalEl = document.getElementById('total');
    const toast = document.getElementById('toast');
    let discount = 0;

    const money = value => new Intl.NumberFormat('ar-AE-u-nu-latn', {
      minimumFractionDigits: 2,
      maximumFractionDigits: 2
    }).format(value);

    function updateTotals() {
      const subtotal = items.reduce((sum, item) => {
        const quantity = Number(item.querySelector('.quantity').textContent);
        return sum + Number(item.dataset.price) * quantity;
      }, 0);

      const delivery = subtotal >= 100 ? 0 : 10;
      const taxable = Math.max(0, subtotal - discount);
      const vat = taxable * 0.05;
      const total = taxable + delivery + vat;

      subtotalEl.textContent = `${money(subtotal)} د.إ`;
      deliveryEl.textContent = delivery === 0 ? 'مجاني' : `${money(delivery)} د.إ`;
      vatEl.textContent = `${money(vat)} د.إ`;
      totalEl.textContent = `${money(total)} د.إ`;
    }

    items.forEach(item => {
      const quantityEl = item.querySelector('.quantity');
      const minus = item.querySelector('.minus');
      const plus = item.querySelector('.plus');

      function refreshControls() {
        const quantity = Number(quantityEl.textContent);
        minus.disabled = quantity === 1;
        plus.disabled = quantity === 9;
      }

      minus.addEventListener('click', () => {
        if (Number(quantityEl.textContent) > 1) {
          quantityEl.textContent = Number(quantityEl.textContent) - 1;
          refreshControls();
          updateTotals();
        }
      });

      plus.addEventListener('click', () => {
        if (Number(quantityEl.textContent) < 9) {
          quantityEl.textContent = Number(quantityEl.textContent) + 1;
          refreshControls();
          updateTotals();
        }
      });

      refreshControls();
    });

    document.getElementById('applyPromo').addEventListener('click', () => {
      const input = document.getElementById('promoCode');
      const message = document.getElementById('promoMessage');
      const code = input.value.trim().toUpperCase();

      if (code === 'TATWEER10') {
        discount = 7.60;
        message.textContent = 'تم تطبيق خصم 10٪ على طلبك.';
        message.style.color = 'var(--green)';
        message.classList.add('show');
      } else {
        discount = 0;
        message.textContent = code ? 'رمز الخصم غير صالح، يرجى المحاولة مرة أخرى.' : 'أدخل رمز الخصم أولًا.';
        message.style.color = 'var(--danger)';
        message.classList.add('show');
      }
      updateTotals();
    });

    document.getElementById('placeOrder').addEventListener('click', () => {
